pub type Suit = enum {
  Clubs,
  Diamonds,
  Hearts,
  Spades,
} derive[Eq, Hash, Ord, Clone]

fn beats(a: &Suit, b: &Suit) -> Bool {
  return a > b;
}

fn main() -> Int {
  let spades = Suit.Spades;
  let hearts = Suit.Hearts;
  if beats(&spades, &hearts) {
    return 1;
  }
  return 0;
}
